import clusterdata.datatypes.JobEvent;
import clusterdata.datatypes.TaskEvent;
import clusterdata.io.GzipCsvSource;
import clusterdata.io.SingleFileSinkFunction;
import clusterdata.utils.AppBase;
import org.apache.flink.api.common.eventtime.WatermarkStrategy;
import org.apache.flink.api.common.functions.AggregateFunction;
import org.apache.flink.api.common.state.ValueState;
import org.apache.flink.api.common.state.ValueStateDescriptor;
import org.apache.flink.api.java.tuple.Tuple2;
import org.apache.flink.api.java.utils.ParameterTool;
import org.apache.flink.streaming.api.datastream.ConnectedStreams;
import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.datastream.SingleOutputStreamOperator;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.co.KeyedCoProcessFunction;
import org.apache.flink.streaming.api.functions.windowing.ProcessWindowFunction;
import org.apache.flink.streaming.api.windowing.assigners.EventTimeSessionWindows;
import org.apache.flink.streaming.api.windowing.time.Time;
import org.apache.flink.streaming.api.windowing.windows.TimeWindow;
import org.apache.flink.util.Collector;

import java.time.Duration;

public class LongestSessionPerJob extends AppBase {

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        final int sesssizeSeconds = params.getInt("sesssize", 600);

        if (taskInput == null || jobInput == null || outputPath == null) {
            throw new IllegalArgumentException("Required parameters: --task_input <path> --job_input <path> --output <path>");
        }

        // set up streaming execution environment
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.getConfig().setAutoWatermarkInterval(1_000L);

        WatermarkStrategy<TaskEvent> taskWms = WatermarkStrategy
                .<TaskEvent>forBoundedOutOfOrderness(Duration.ofMinutes(1))
                .withTimestampAssigner((e, previousTs) -> e.getTimeMillis());

        WatermarkStrategy<JobEvent> jobWms = WatermarkStrategy
                .<JobEvent>forBoundedOutOfOrderness(Duration.ofMinutes(1))
                .withTimestampAssigner((e, previousTs) -> e.getTimeMillis());

        DataStream<TaskEvent> taskEventsStream = env
                .addSource(taskSourceOrTest(new GzipCsvSource<>(taskInput, TaskEvent::fromCsvLine)))
                .name("task-events");

        DataStream<JobEvent> jobEventsStream = env
                .addSource(jobSourceOrTest(new GzipCsvSource<>(jobInput, JobEvent::fromCsvLine)))
                .name("job-events");

        SingleOutputStreamOperator<TaskEvent> submits = taskEventsStream
                .assignTimestampsAndWatermarks(taskWms)
                .filter(e -> e.jobId >= 0 && e.eventType == TaskEvent.EVENT_SUBMIT)
                .name("task-submit-events");

        SingleOutputStreamOperator<JobEvent> finishedJobs = jobEventsStream
                .assignTimestampsAndWatermarks(jobWms)
                .filter(e -> e.jobId >= 0 && e.eventType == JobEvent.EVENT_FINISH)
                .name("job-finish-events");

        SingleOutputStreamOperator<JobStageCount> stageCounts = submits
                .keyBy(e -> e.jobId)
                .window(EventTimeSessionWindows.withGap(Time.seconds(sesssizeSeconds)))
                .aggregate(new CountSubmitsAgg(), new AttachWindowInfo())
                .name("stage-counts");

        ConnectedStreams<JobStageCount, JobEvent> connected = stageCounts
                .connect(finishedJobs)
                .keyBy(sc -> sc.jobId, je -> je.jobId);

        SingleOutputStreamOperator<Tuple2<Long, Long>> longestStagePerFinishedJob = connected
                .process(new EmitLongestStageWhenFinished(sesssizeSeconds))
                .name("longest-stage-per-finished-job");

        DataStream<String> outputLines = longestStagePerFinishedJob
                .map(t -> "(" + t.f0 + "," + t.f1 + ")")
                .name("format-output");

        outputLines
                .addSink(sinkOrTest(new SingleFileSinkFunction(outputPath)))
                .name("file-output")
                .setParallelism(1);

        env.execute("LongestSessionPerJob");
    }

    public static class JobStageCount {
        public long jobId;
        public long taskCount;
        public long windowEndMillis;

        public JobStageCount() {
        }

        public JobStageCount(long jobId, long taskCount, long windowEndMillis) {
            this.jobId = jobId;
            this.taskCount = taskCount;
            this.windowEndMillis = windowEndMillis;
        }
    }

    public static class CountSubmitsAgg implements AggregateFunction<TaskEvent, Long, Long> {
        @Override
        public Long createAccumulator() {
            return 0L;
        }

        @Override
        public Long add(TaskEvent value, Long accumulator) {
            return accumulator + 1L;
        }

        @Override
        public Long getResult(Long accumulator) {
            return accumulator;
        }

        @Override
        public Long merge(Long a, Long b) {
            return a + b;
        }
    }

    public static class AttachWindowInfo extends ProcessWindowFunction<Long, JobStageCount, Long, TimeWindow> {
        @Override
        public void process(Long key, Context context, Iterable<Long> elements, Collector<JobStageCount> out) {
            Long count = elements.iterator().next();
            out.collect(new JobStageCount(key, count, context.window().getEnd()));
        }
    }

    /**
     * Waits for a job FINISH event, then emits the maximum stage size.
     *
     * We delay emission to (finish_time + session_gap) in event time, so that the
     * last session window has time to close and emit its count.
     */
    public static class EmitLongestStageWhenFinished
            extends KeyedCoProcessFunction<Long, JobStageCount, JobEvent, Tuple2<Long, Long>> {

        private final long sessionGapMillis;

        private transient ValueState<Long> maxStageCount;
        private transient ValueState<Boolean> sawFinish;
        private transient ValueState<Long> finishEmitTimer;

        public EmitLongestStageWhenFinished(int sessionGapSeconds) {
            this.sessionGapMillis = sessionGapSeconds * 1000L;
        }

        @Override
        public void open(org.apache.flink.configuration.Configuration parameters) {
            maxStageCount = getRuntimeContext().getState(new ValueStateDescriptor<>("maxStageCount", Long.class));
            sawFinish = getRuntimeContext().getState(new ValueStateDescriptor<>("sawFinish", Boolean.class));
            finishEmitTimer = getRuntimeContext().getState(new ValueStateDescriptor<>("finishEmitTimer", Long.class));
        }

        @Override
        public void processElement1(JobStageCount value, Context ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
            Long currentMax = maxStageCount.value();
            if (currentMax == null || value.taskCount > currentMax) {
                maxStageCount.update(value.taskCount);
            }
        }

        @Override
        public void processElement2(JobEvent value, Context ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
            sawFinish.update(true);

            long timerTs = value.getTimeMillis() + sessionGapMillis + 1L;
            Long existing = finishEmitTimer.value();
            if (existing == null || timerTs > existing) {
                if (existing != null) {
                    ctx.timerService().deleteEventTimeTimer(existing);
                }
                ctx.timerService().registerEventTimeTimer(timerTs);
                finishEmitTimer.update(timerTs);
            }
        }

        @Override
        public void onTimer(long timestamp, OnTimerContext ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
            Boolean finished = sawFinish.value();
            if (Boolean.TRUE.equals(finished)) {
                Long max = maxStageCount.value();
                out.collect(Tuple2.of(ctx.getCurrentKey(), max == null ? 0L : max));
            }

            maxStageCount.clear();
            sawFinish.clear();
            finishEmitTimer.clear();
        }
    }
}
