{"command": "create", "path": "/app/workspace/src/main/java/clusterdata/io/GzipCsvSource.java", "security_risk": "MEDIUM", "file_text": "package clusterdata.io;

import org.apache.flink.streaming.api.functions.source.SourceFunction;

import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Serializable;
import java.nio.charset.StandardCharsets;
import java.util.zip.GZIPInputStream;

/**
 * Simple single-file source for gzipped CSV files.
 *
 * This is intentionally minimal (no checkpointing), intended for bounded batch-style jobs.
 */
public class GzipCsvSource<T> implements SourceFunction<T>, Serializable {

    @FunctionalInterface
    public interface LineParser<T> extends Serializable {
        T parse(String line) throws Exception;
    }

    private final String path;
    private final LineParser<T> parser;

    private volatile boolean canceled = false;

    public GzipCsvSource(String path, LineParser<T> parser) {
        if (path == null) {
            throw new IllegalArgumentException("path must not be null");
        }
        if (parser == null) {
            throw new IllegalArgumentException("parser must not be null");
        }
        this.path = path;
        this.parser = parser;
    }

    @Override
    public void run(SourceContext<T> ctx) throws Exception {
        try (InputStream fis = new FileInputStream(path);
             InputStream is = path.endsWith(".gz") ? new GZIPInputStream(fis) : fis;
             BufferedReader br = new BufferedReader(new InputStreamReader(is, StandardCharsets.UTF_8))) {

            String line;
            while (!canceled && (line = br.readLine()) != null) {
                if (line.isEmpty()) {
                    continue;
                }
                T parsed = parser.parse(line);
                synchronized (ctx.getCheckpointLock()) {
                    ctx.collect(parsed);
                }
            }
        } catch (IOException ioe) {
            throw new RuntimeException("Failed reading input file: " + path, ioe);
        }
    }

    @Override
    public void cancel() {
        canceled = true;
    }
}
"}

{"command": "create", "path": "/app/workspace/src/main/java/clusterdata/io/SingleFileSinkFunction.java", "security_risk": "MEDIUM", "file_text": "package clusterdata.io;

import org.apache.flink.configuration.Configuration;
import org.apache.flink.streaming.api.functions.sink.RichSinkFunction;

import java.io.BufferedWriter;
import java.io.File;
import java.io.FileOutputStream;
import java.io.OutputStreamWriter;
import java.nio.charset.StandardCharsets;

/**
 * Sink that writes all records into a single local file.
 *
 * Set sink parallelism to 1 when using this.
 */
public class SingleFileSinkFunction extends RichSinkFunction<String> {

    private final String outputPath;

    private transient BufferedWriter writer;

    public SingleFileSinkFunction(String outputPath) {
        this.outputPath = outputPath;
    }

    @Override
    public void open(Configuration parameters) throws Exception {
        File f = new File(outputPath);
        File parent = f.getParentFile();
        if (parent != null) {
            parent.mkdirs();
        }
        this.writer = new BufferedWriter(new OutputStreamWriter(new FileOutputStream(f, false), StandardCharsets.UTF_8));
    }

    @Override
    public synchronized void invoke(String value, Context context) throws Exception {
        writer.write(value);
        writer.newLine();
    }

    @Override
    public void close() throws Exception {
        if (writer != null) {
            writer.flush();
            writer.close();
        }
    }
}
