 * CSV columns (v2.1):
 * 0: time (microseconds)
 * 1: missing info
 * 2: job ID
 * 3: event type
 * 4: user
 * 5: scheduling class
 * 6: job name
 * 7: logical job name
 */
public class JobEvent implements Serializable {

    public static final int EVENT_FINISH = 4;

    public long timeMicros;
    public String missingInfo;
    public long jobId;
    public int eventType;
    public String user;
    public int schedulingClass;
    public String jobName;
    public String logicalJobName;

    public JobEvent() {
        // Flink POJO
    }

    public long getTimeMillis() {
        return timeMicros / 1000L;
    }

    public long getJobId() {
        return jobId;
    }

    public int getEventType() {
        return eventType;
    }

    public static JobEvent fromCsvLine(String line) {
        String[] p = line.split(",", -1);
        if (p.length < 4) {
            throw new IllegalArgumentException("Invalid job_events line (expected >= 4 columns): " + line);
        }

        JobEvent e = new JobEvent();
        e.timeMicros = parseLong(p[0], 0L);
        e.missingInfo = emptyToNull(get(p, 1));
        e.jobId = parseLong(get(p, 2), -1L);
        e.eventType = (int) parseLong(get(p, 3), -1L);
        e.user = emptyToNull(get(p, 4));
        e.schedulingClass = (int) parseLong(get(p, 5), -1L);
        e.jobName = emptyToNull(get(p, 6));
        e.logicalJobName = emptyToNull(get(p, 7));
        return e;
    }

    private static String get(String[] parts, int idx) {
        return idx < parts.length ? parts[idx] : "";
    }

    private static String emptyToNull(String s) {
        if (s == null) {
            return null;
        }
        String t = s.trim();
        return t.isEmpty() ? null : t;
    }

    private static long parseLong(String s, long defaultValue) {
        String t = emptyToNull(s);
        if (t == null) {
            return defaultValue;
        }
        return Long.parseLong(t);
    }
}
